using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.PaymentVouchers;using Namaa.Api.Extensions;using Namaa.Application.PaymentVouchers.Commands.AddPaymentVoucherAllocation;using Namaa.Application.PaymentVouchers.Commands.CreatePaymentVoucher;using Namaa.Application.PaymentVouchers.Queries.GetPaymentVoucherById;using Namaa.Application.PaymentVouchers.Queries.GetPaymentVouchers;namespace Namaa.Api.Controllers;[ApiController][Route("api/payment-vouchers")]public sealed class PaymentVouchersController(ISender sender):ControllerBase{[HttpPost]public async Task<IActionResult>Create(CreatePaymentVoucherRequest request,CancellationToken cancellationToken){var result=await sender.Send(new CreatePaymentVoucherCommand(request.VoucherNumber,request.VoucherDate,request.PaymentMethod,request.Amount,request.PaidByUserId,request.SupplierId,request.BeneficiaryName,request.ProjectId,request.ReferenceNumber,request.Notes),cancellationToken);return result.IsFailure?result.ToActionResult(this):CreatedAtAction(nameof(GetById),new{id=result.Value.Id},result.Value);}[HttpGet]public async Task<IActionResult>GetAll(CancellationToken cancellationToken)=>(await sender.Send(new GetPaymentVouchersQuery(),cancellationToken)).ToActionResult(this);[HttpGet("{id:long}")]public async Task<IActionResult>GetById(long id,CancellationToken cancellationToken)=>(await sender.Send(new GetPaymentVoucherByIdQuery(id),cancellationToken)).ToActionResult(this);[HttpPost("{id:long}/allocations")]public async Task<IActionResult>AddAllocation(long id,AddPaymentVoucherAllocationRequest request,CancellationToken cancellationToken)=>(await sender.Send(new AddPaymentVoucherAllocationCommand(id,request.PurchaseInvoiceId,request.AllocatedAmount),cancellationToken)).ToActionResult(this);}
